// Weekly report: read-only aggregation. Counts only; no names, titles, drafts or notes are ever output.
const TZ = "America/New_York";
const rows = name => { let items = []; try { items = $(name).all(); } catch (e) { items = []; } return items.map(i => i && i.json).filter(j => j && j.id); };
const props = p => (p && typeof p.properties === "object" && p.properties) || {};
const text = v => !v ? "" : Array.isArray(v.title) ? v.title.map(t => t.plain_text || "").join("") : Array.isArray(v.rich_text) ? v.rich_text.map(t => t.plain_text || "").join("")
  : v.select ? (v.select.name || "") : v.status ? (v.status.name || "") : "";
const find = (p, re) => { const pr = props(p); for (const k in pr) if (re.test(k)) return pr[k]; return null; };
const sel = (p, re) => String(text(find(p, re))).trim();

const fmt = new Intl.DateTimeFormat("en-CA", { timeZone: TZ, year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", hourCycle: "h23" });
const parts = t => { const o = {}; for (const x of fmt.formatToParts(new Date(t))) o[x.type] = x.value; return o; };
const ymdOf = t => { const o = parts(t); return o.year + "-" + o.month + "-" + o.day; };
const addDays = (ymd, n) => { const [y, m, d] = ymd.split("-").map(Number); return new Date(Date.UTC(y, m - 1, d + n)).toISOString().slice(0, 10); };
const midnight = ymd => { // instant of 00:00 America/New_York on ymd
  const [y, m, d] = ymd.split("-").map(Number); const base = Date.UTC(y, m - 1, d);
  for (const h of [4, 5, 6]) { const t = base + h * 3600000; const o = parts(t); if (o.year + "-" + o.month + "-" + o.day === ymd && Number(o.hour) === 0) return t; }
  return base + 5 * 3600000;
};
const nowMs = Date.now();
const week_end = ymdOf(nowMs), week_start = addDays(week_end, -6);
const lo = midnight(week_start), hi = midnight(addDays(week_end, 1)); // [lo, hi)

const toMs = s => { // ISO string -> ms; date-only means midnight New York; null when unusable
  if (typeof s !== "string" || !s) return null;
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return midnight(s);
  const t = Date.parse(s); return Number.isNaN(t) ? null : t;
};
const inWin = ms => ms !== null && ms >= lo && ms < hi;
const dateOf = (p, re) => { const v = find(p, re); return v && v.date ? toMs(v.date.start) : null; };
const createdOf = p => { // created_time on the page, else a Created property
  const c = toMs(p.created_time); if (c !== null) return c;
  const v = find(p, /^created$/i); return v && typeof v.created_time === "string" ? toMs(v.created_time) : null;
};

// Agents
const KNOWN = ["Conductor", "Router", "Estimator", "Marketer", "Builder", "Support", "QA", "Engineer", "Researcher", "Developer", "Shield/Ops"];
const alias = { Estimate: "Estimator", Content: "Marketer", Integrator: "Conductor" };
const runs_by_agent = {};
for (const n of KNOWN) runs_by_agent[n] = { runs: 0, errors: 0 };
for (const p of rows("Notion Activity Log")) {
  const ms = dateOf(p, /^timestamp$/i) ?? createdOf(p);
  if (!inWin(ms)) continue;
  let a = sel(p, /^agent$/i).replace(/ Agent$/, "").slice(0, 40);
  if (Object.prototype.hasOwnProperty.call(alias, a)) a = alias[a];
  if (!a || a === "__proto__") a = "Unknown";
  if (!Object.prototype.hasOwnProperty.call(runs_by_agent, a)) runs_by_agent[a] = { runs: 0, errors: 0 };
  runs_by_agent[a].runs++;
  if (sel(p, /^status$/i) === "Error") runs_by_agent[a].errors++;
}

// Approvals
const approvals = { created: 0, approved: 0, rejected: 0, sent: 0, awaiting: 0 };
const qa = { pass: 0, fail: 0, not_checked: 0 };
for (const p of rows("Notion Approvals")) {
  const status = sel(p, /^status$/i);
  const created = createdOf(p);
  if (inWin(created)) {
    approvals.created++;
    if (status === "Awaiting Approval") approvals.awaiting++;
    const q = sel(p, /^qa result$/i);
    if (q === "Pass") qa.pass++; else if (q === "Fail") qa.fail++; else qa.not_checked++;
  }
  if (inWin(dateOf(p, /^decided at$/i))) {
    if (status === "Approved") approvals.approved++;
    else if (status === "Rejected") approvals.rejected++;
    else if (status === "Sent") approvals.sent++;
  }
}

// Pipeline (by created_time)
const by_status = { "Booked": 0, "In Progress": 0, "Awaiting Invoice": 0, "Paid": 0, "Flagged": 0 };
for (const p of rows("Notion Pipeline")) {
  if (!inWin(createdOf(p))) continue;
  let s = sel(p, /^status$/i).slice(0, 40);
  if (!s || s === "__proto__") s = "Unknown";
  by_status[s] = (by_status[s] || 0) + 1;
}
const jobs = { by_status, flagged: by_status["Flagged"] };

return [{ json: { body: { week_start, week_end, runs_by_agent, approvals, qa, jobs, generated_at: new Date(nowMs).toISOString() } } }];
